function getCharacterMetrics(codepoint, fontName) {
  if (codepoint === void 0) codepoint = 77;
  const metrics = font_metrics_data_default[fontName][codepoint];

  if (metrics) {
    return {
      defaultMetrics: false,
      depth: metrics[0],
      height: metrics[1],
      italic: metrics[2],
      skew: metrics[3],
      width: metrics[4]
    };
  }

  if (codepoint === 11034) {
    return {
      defaultMetrics: true,
      depth: 0.2,
      height: 0.8,
      italic: 0,
      skew: 0,
      width: 0.8
    };
  }

  const char = String.fromCodePoint(codepoint);
  if (char in EXTRA_CHARACTER_MAP) codepoint = EXTRA_CHARACTER_MAP[char].codePointAt(0);else if (CJK_REGEX.test(char)) {
    codepoint = 77;
    return {
      defaultMetrics: true,
      depth: 0.2,
      height: 0.9,
      italic: 0,
      skew: 0,
      width: 1
    };
  }
  return {
    defaultMetrics: true,
    depth: 0.2,
    height: 0.7,
    italic: 0,
    skew: 0,
    width: 0.8
  };
} // src/core/svg-box.ts


